// @generated by:gauntlet run:anatoly-orion-recon
mod common;

use anatoly::{scan::scan_configured, scan_options::ScanOptions};
use common::{Server, limits, response};
use serde_json::Value;
use std::process::Command;

fn options() -> ScanOptions {
    let mut options = ScanOptions {
        samples: 1,
        paths: vec![],
        ..ScanOptions::default()
    };
    options.network.no_proxy = true;
    options
}

fn scan(server: &Server, options: &ScanOptions, requests: usize) -> Value {
    let mut budget = limits();
    budget.max_requests = requests;
    budget.max_body = 32_768;
    serde_json::to_value(scan_configured(&server.url, budget, options).unwrap()).unwrap()
}

#[test]
fn t_ac_11_disclosed_diagnostics_support_structured_html_and_extensionless_metadata_paths() {
    let server = Server::new(|path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                r#"
                <a href=/debug/phpinfo>one</a><form action='/php-info'>two</form>
                <a HREF='/debug/info'>three</a><a href='/debug/version'>four</a>
                <a href='/diagnostics?sample=PRIVATE_FIXTURE&amp;mode=1'>five</a>
                <a href='/meta/composer.json'>six</a><a href='/meta/composer.lock'>seven</a>"#,
            )
        } else {
            response("404 Not Found", "", "missing")
        }
    });
    let mut settings = options();
    settings.max_linked_paths = 16;

    let report = scan(&server, &settings, 16);

    let paths = server.paths.lock().unwrap().clone();
    for expected in [
        "/debug/phpinfo",
        "/php-info",
        "/debug/info",
        "/debug/version",
        "/diagnostics",
        "/meta/composer.json",
        "/meta/composer.lock",
    ] {
        assert!(
            paths.iter().any(|p| p == expected),
            "missing {expected}: {paths:?}"
        );
    }
    assert_eq!(report["requests_sent"], 8);
    assert_eq!(report["analysis"]["coverage_complete"], true);
    assert!(!report.to_string().contains("PRIVATE_FIXTURE"));
    assert!(paths.iter().all(|path| !path.contains('?')));
}

#[test]
fn t_ac_11_inert_markup_and_arbitrary_html_robot_directives_never_schedule_requests() {
    let server = Server::new(|_| {
        response(
            "200 OK",
            "",
            r#"
        <!-- <a href='/comment/phpinfo.php'>example</a> -->
        <script>const example = '<a href="/script/info.php">info</a>';</script>
        <template><a href='/template/phpinfo'>example</a></template>
        <pre><a href='/pre/version'>example</a></pre>
        <code><a href='/code/composer.json'>example</a></code>
        <p>Example robot directive:</p>
        Disallow: /fake-robots/phpinfo.php
        "#,
        )
    });

    let report = scan(&server, &options(), 16);

    assert_eq!(server.paths.lock().unwrap().as_slice(), ["/"]);
    assert!(report["discovered_paths"].as_array().unwrap().is_empty());
}

#[test]
fn t_ac_11_literal_active_article_links_remain_eligible_for_diagnostic_discovery() {
    let server = Server::new(|path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                "<article><a href='/article/phpinfo.php'>Diagnostic</a></article>",
            )
        } else {
            response("200 OK", "", r#"{"php_version":"8.4.26"}"#)
        }
    });

    let report = scan(&server, &options(), 4);

    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/article/phpinfo.php"]
    );
    assert_eq!(report["version_status"], "affected_range");
}

#[test]
fn t_ac_11_excessive_html_depth_reports_incomplete_analysis_without_forged_php_evidence() {
    let body = format!(
        "{}<p>Powered by CraftCMS</p>{}",
        "<div>".repeat(160),
        "</div>".repeat(160)
    );
    let server = Server::new(move |_| response("200 OK", "", &body));
    let mut settings = options();
    settings.discover = false;

    let report = scan(&server, &settings, 4);

    assert_eq!(report["analysis"]["coverage_complete"], false);
    assert!(
        report["analysis"]["gaps"]
            .as_array()
            .unwrap()
            .iter()
            .any(|gap| {
                let text = gap.as_str().unwrap().to_ascii_lowercase();
                text.contains("html") || text.contains("depth")
            }),
        "{report}"
    );
    assert!(report["version"].is_null());
    assert!(report["evidence"].as_array().unwrap().is_empty());
    assert_eq!(report["verdict"], "inconclusive");
}

#[test]
fn t_ac_11_diagnostics_remain_same_origin_and_never_fetch_unrelated_links() {
    let external = Server::new(|_| response("200 OK", "", "must not be requested"));
    let external_url = external.url.clone();
    let server = Server::new(move |_| {
        response(
            "200 OK",
            "",
            &format!(
                "<a href='{external_url}phpinfo.php'>outside</a><a href='/ordinary.php'>normal</a>"
            ),
        )
    });

    let report = scan(&server, &options(), 16);

    assert_eq!(report["requests_sent"], 1);
    assert!(report["discovered_paths"].as_array().unwrap().is_empty());
    assert!(external.paths.lock().unwrap().is_empty());
}

#[test]
fn t_ac_11_excluded_links_do_not_consume_the_capacity_of_permitted_diagnostics() {
    let server = Server::new(|path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                "<a href='/private/info.php'>excluded</a><a href='/public/phpinfo.php'>allowed</a>",
            )
        } else {
            response("200 OK", "", r#"{"php_version":"8.4.26"}"#)
        }
    });
    let mut settings = options();
    settings.max_linked_paths = 1;
    settings.network.exclude_paths.push("/private/".into());

    let report = scan(&server, &settings, 4);

    let paths = server.paths.lock().unwrap().clone();
    assert_eq!(paths, ["/", "/public/phpinfo.php"]);
    assert_eq!(report["analysis"]["discovery_limited"], false);
    assert_eq!(report["version_status"], "affected_range");
}

#[test]
fn t_ac_11_a_link_cap_reports_incomplete_discovery_instead_of_complete_coverage() {
    let server = Server::new(|path| {
        if path == "/" {
            response(
                "200 OK",
                "",
                "<a href='/one/info.php'>one</a><a href='/two/info.php'>two</a>",
            )
        } else {
            response("404 Not Found", "", "missing")
        }
    });
    let mut settings = options();
    settings.max_linked_paths = 1;

    let report = scan(&server, &settings, 4);

    assert_eq!(report["discovered_paths"].as_array().unwrap().len(), 1);
    assert_eq!(report["analysis"]["discovery_limited"], true);
    assert_eq!(report["analysis"]["coverage_complete"], false);
    assert!(!report["analysis"]["gaps"].as_array().unwrap().is_empty());
    let scope = report["analysis"]["coverage_scope"]
        .as_str()
        .unwrap()
        .to_ascii_lowercase();
    assert!(scope.contains("plan") && scope.contains("not exhaustive"));
}

