#[test]
fn t_ac_11_deep_scans_observe_robots_and_composer_before_guessed_diagnostic_paths() {
    let server = Server::new(|path| {
        if path == "/" {
            response("200 OK", "", "application")
        } else {
            response("404 Not Found", "", "missing")
        }
    });
    let mut settings = options();
    settings.deep = true;
    settings.paths.push("guessed/phpinfo.php".into());

    scan(&server, &settings, 4);

    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/robots.txt", "/composer.json", "/composer.lock"]
    );
}

#[test]
fn t_ac_11_robots_disclosed_routes_beat_pending_guesses_within_the_shared_budget() {
    let server = Server::new(|path| match path {
        "/" => response("200 OK", "", "application"),
        "/robots.txt" => response(
            "200 OK",
            "Content-Type: text/plain\r\n",
            "User-agent: *\nDisallow: /observed/phpinfo.php\n",
        ),
        "/observed/phpinfo.php" => response("200 OK", "", r#"{"php_version":"8.4.26"}"#),
        _ => response("404 Not Found", "", "missing"),
    });
    let mut settings = options();
    settings.deep = true;

    let report = scan(&server, &settings, 3);

    assert_eq!(
        server.paths.lock().unwrap().as_slice(),
        ["/", "/robots.txt", "/observed/phpinfo.php"]
    );
    assert_eq!(report["version_status"], "affected_range");
    assert_eq!(report["requests_sent"], 3);
}

#[test]
fn t_ac_11_cli_dry_runs_expose_profile_link_caps_without_changing_request_caps() {
    let server = Server::new(|_| response("200 OK", "", "not requested"));
    for (flags, expected, requests) in [
        (vec![], 3, 8),
        (vec!["--profile", "thorough"], 16, 32),
        (vec!["--deep"], 16, 32),
        (vec!["--max-linked-paths", "0"], 0, 8),
        (vec!["--max-linked-paths", "128"], 128, 8),
    ] {
        let output = Command::new(env!("CARGO_BIN_EXE_anatoly"))
            .args(["scan", &server.url, "--dry-run", "--json", "--no-proxy"])
            .args(flags)
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let plan: Value = serde_json::from_slice(&output.stdout).unwrap();
        assert_eq!(plan["configuration"]["max_linked_paths"], expected);
        assert_eq!(plan["configuration"]["max_requests"], requests);
    }
    let invalid = Command::new(env!("CARGO_BIN_EXE_anatoly"))
        .args([
            "scan",
            &server.url,
            "--dry-run",
            "--json",
            "--max-linked-paths",
            "129",
        ])
        .output()
        .unwrap();
    assert!(!invalid.status.success());
    assert!(invalid.stdout.is_empty());
    assert!(server.paths.lock().unwrap().is_empty());
}
